const body = $('Webhook').first().json.body;
const specialty = body.specialty;
const raw = body.date;

const IST = 5.5 * 3600000;
const now = new Date(Date.now() + IST);
let d = new Date(now);
if (raw === 'tomorrow') d.setUTCDate(d.getUTCDate() + 1);
else if (raw !== 'today') d = new Date(raw + 'T00:00:00Z');
const date = d.toISOString().slice(0, 10);

const doctors = {
  general_physician: { name: "Dr. Ravi Kumar", days: [1,2,3,4,5,6], start: 9.5, end: 13.5 },
  gynecologist:      { name: "Dr. Lakshmi",    days: [2,4,6],       start: 17,  end: 20 },
  pediatrician:      { name: "Dr. Srinivas",   days: [1,3,5],       start: 17.5, end: 20.5 },
};
const doc = doctors[specialty];
if (!doc) return [{ json: { error: "unknown_specialty" } }];

const dayOfWeek = new Date(date + 'T00:00:00').getDay();
if (!doc.days.includes(dayOfWeek)) {
  return [{ json: { date, doctor: doc.name, available_slots: [], note: "doctor_not_available_this_day" } }];
}

const events = $input.all().map(i => i.json).filter(e => e.start && e.start.dateTime);
const pad = n => String(n).padStart(2, '0');
const slots = [];
for (let t = doc.start; t < doc.end; t += 0.5) {
  const h = Math.floor(t), m = (t % 1) * 60;
  const start = new Date(`${date}T${pad(h)}:${pad(m)}:00+05:30`);
  const end = new Date(start.getTime() + 30 * 60000);
  const busy = events.some(e => new Date(e.start.dateTime) < end && new Date(e.end.dateTime) > start);
  if (!busy && start > new Date()) slots.push(`${pad(h)}:${pad(m)}`);
}
return [{ json: { date, doctor: doc.name, available_slots: slots.slice(0, 6) } }];
